from typing import List

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        result = []
        path = []

        def dfs(start: int) -> None:
            if start == len(s):
                if all(part == part[::-1] for part in path):
                    result.append(path.copy())
                return
            for end in range(start + 1, len(s) + 1):
                path.append(s[start:end])
                dfs(end)
                path.pop()

        dfs(0)
        return result

